INSERT INTO _migration_616_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igphy_space_s3_009', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'An absorption line in the spectrum of a distant galaxy has a wavelength of 500 nm, compared with 400 nm for the same line measured in the laboratory. Taking the speed of light as 3.0 × 10⁸ m/s, what can be concluded about the galaxy?', 'multiple_choice', NULL, '["A. It is moving away from us at about 7.5 × 10⁷ m/s","B. It is moving towards us at about 7.5 × 10⁷ m/s","C. It is moving away from us at about 6.0 × 10⁷ m/s","D. It is not moving relative to the Earth"]', 'A', 'The wavelength has increased, so the light is redshifted and the galaxy is receding. The recession speed is v = c × Δλ ÷ λ = 3.0 × 10⁸ × (100 ÷ 400) = 7.5 × 10⁷ m/s. (Approach would produce a blueshift; 6.0 × 10⁷ m/s wrongly uses Δλ ÷ λobserved = 100 ÷ 500.) Therefore the correct answer is A: It is moving away from us at about 7.5 × 10⁷ m/s.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO3', NULL, NULL, 'board_cambridge'),
('q_igphy_space_s3_010', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A satellite in a circular orbit around the Earth moves into a lower orbit. What happens to its orbital speed and its orbital period?', 'multiple_choice', NULL, '["A. Both the speed and the period decrease","B. The speed increases and the period decreases","C. The speed decreases and the period increases","D. Both the speed and the period increase"]', 'B', 'In a lower orbit the gravitational pull is stronger, so the satellite must travel faster to maintain its circular path; the shorter circumference and higher speed together make the orbital period shorter. This is why low-orbit satellites circle the Earth in about 90 minutes while geostationary satellites, much higher up, take 24 hours. Therefore the correct answer is B: The speed increases and the period decreases.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO3', NULL, NULL, 'board_cambridge'),
('q_igphy_space_s3_011', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'The Moon orbits the Earth at an average distance of 3.84 × 10⁸ m with an orbital period of 27.3 days. Assuming the orbit is circular, calculate the orbital speed of the Moon. (1 day = 86,400 s.)', 'calculation', NULL, NULL, 'approximately 1.0 × 10³ m/s', 'The circumference of the orbit is 2πr = 2 × 3.14 × 3.84 × 10⁸ = 2.41 × 10⁹ m. The period in seconds is T = 27.3 × 86,400 = 2.36 × 10⁶ s. Orbital speed v = distance ÷ time = 2.41 × 10⁹ ÷ 2.36 × 10⁶ ≈ 1.02 × 10³ m/s. Answer: the Moon orbits at approximately 1.0 × 10³ m/s (about 1 km/s).', 'medium', '5', '3', '240', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_space_s3_012', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Explain why the Sun is classified as a star but Jupiter is not.', 'short_answer', NULL, NULL, 'The Sun releases its own energy by nuclear fusion of hydrogen in its core and emits its own light and heat, while Jupiter is a planet: it is not massive enough for fusion and shines only by reflecting sunlight.', 'A star is a body massive enough for gravity to compress and heat its core until nuclear fusion begins, so it generates and emits its own energy. Jupiter, although large for a planet, has far too little mass for fusion to start; it produces no light of its own and is visible only because it reflects sunlight. Therefore the Sun is a star and Jupiter is a planet.', 'medium', '3', '2', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_space_s3_013', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Astronomers can describe the life cycle of a star such as the Sun.', 'structured', NULL, NULL, '(a) A cloud of gas and dust (a nebula) collapses under its own gravitational attraction into an increasingly dense protostar; as it contracts it heats up until the core is hot and dense enough for the nuclear fusion of hydrogen to begin. (b) The star expands and its surface cools to become a red giant; it then sheds its outer layers as a planetary nebula, leaving the hot core behind as a white dwarf, which gradually cools and fades. (c) A much more massive star explodes as a supernova, leaving behind a neutron star — or, if the remaining core is massive enough, a black hole — instead of quietly becoming a white dwarf.', '(a) A cloud of gas and dust (a nebula) collapses under its own gravitational attraction into an increasingly dense protostar; as it contracts it heats up until the core is hot and dense enough for the nuclear fusion of hydrogen to begin. (b) The star expands and its surface cools to become a red giant; it then sheds its outer layers as a planetary nebula, leaving the hot core behind as a white dwarf, which gradually cools and fades. (c) A much more massive star explodes as a supernova, leaving behind a neutron star — or, if the remaining core is massive enough, a black hole — instead of quietly becoming a white dwarf.', 'hard', '7', '7', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_616_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_igphy_space_s3_013_a', 'q_igphy_space_s3_013', 'a', 'Describe how a star forms from a nebula.', '2', 'A cloud of gas and dust (a nebula) collapses under its own gravitational attraction into an increasingly dense protostar; as it contracts it heats up until the core is hot and dense enough for the nuclear fusion of hydrogen to begin.', '1'),
('sqp_q_igphy_space_s3_013_b', 'q_igphy_space_s3_013', 'b', 'Describe what happens to a star like the Sun when it runs out of hydrogen fuel.', '3', 'The star expands and its surface cools to become a red giant; it then sheds its outer layers as a planetary nebula, leaving the hot core behind as a white dwarf, which gradually cools and fades.', '2'),
('sqp_q_igphy_space_s3_013_c', 'q_igphy_space_s3_013', 'c', 'State how the final stages differ for a star with a much greater mass than the Sun.', '2', 'A much more massive star explodes as a supernova, leaving behind a neutron star — or, if the remaining core is massive enough, a black hole — instead of quietly becoming a white dwarf.', '3');
INSERT INTO _migration_616_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_616_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_616_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_616_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_616_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_616_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-physics-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/', 0, 1 FROM _migration_616_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_616_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_616_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 5 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_616_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 5 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_616_expected e ON e.id = q.id) = 5 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_616_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
